    public static function path(string $name): string
    {
        return self::PATHS[$name] ?? self::PATHS['circle'];
    }

    public static function svg(string $name, int $size = 16, string $class = '', $strokeWidth = 2): string
    {
        $classAttr = $class !== '' ? ' class="' . e($class) . '"' : '';

        return '<svg' . $classAttr . ' width="' . (int) $size . '" height="' . (int) $size
            . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' . $strokeWidth
            . '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'
            . self::path($name) . '</svg>';
    }
